  "python": "def pilot_policy(trace):
    allowed_for_sms = {"PII"}
    for action, label in trace:
        params = json.loads(action.arguments)
        destination = None
        if action.name == "frontdesk/notify":
            if params.get("target") == "sms":
                destination = "sms"
        elif action.name == "events/export":
            if params.get("source") == "agenda":
                destination = None
            else:
                destination = "website"
        if destination == "sms":
            if not label.subset.issubset(allowed_for_sms):
                raise PolicyViolation("SMS service only allows PII.")
    return None"
